# Consolidate overlapping topics so the guide stays near the requested length.
REMOVE_PAGES = {
    "Read Explorer results", "Download Explorer results", "Filter rankings by category",
    "Read the activity chart", "Filter company and sector examples",
    "Prepare a responsible Kenya presentation", "Understand chronological holdout",
    "Read time-series cross-validation", "Probability, score, and confidence",
    "Inspect research source details", "Common errors: search and empty pages",
    "Frequently asked questions: data and ethics", "User checklist before presenting",
    "Use the Command Center as a demo starting point",
}
PAGES = [item for item in PAGES if item['title'] not in REMOVE_PAGES]
PAGES = sorted(PAGES, key=lambda item: item['chapter'] if item['chapter'] else 99)

# Feature-specific orientation paragraphs give first-time readers context for the
# controls shown on the page. They deliberately describe only the inspected UI.
PAGE_GUIDANCE = {
    'Open the application': 'Start TechPulse from its project folder before opening your browser. Keep the PowerShell window open so you can read the local address and any startup messages. A page that opens confirms that TechPulse is running; it does not confirm that Research data passed validation or that enough evidence is available for a model.',
    'Check the first screen': 'The Command Center is the landing page, while the sidebar remains the main way to change views. First identify the active data mode and read the status banner. Then match the displayed cards to their labels and scope. This quick check prevents a populated synthetic example from being mistaken for an observation stored in PostgreSQL.',
    'Use sidebar navigation': 'The sidebar groups the pages available in the selected mode. Its contents can change when the data mode changes, so a missing page may be unavailable in Research mode. Select one page at a time, wait for the page to update, and confirm its title before interpreting its charts or tables.',
    'Understand common controls': 'Most pages use a selector for technology, category, metric, model, or period, followed by a chart or table. A selection updates the displayed view when the app reruns; it does not create a new source record. In the annotated figures, A marks page navigation, B the data-mode selector, and C the current page and its controls.',
    'Command Center overview': 'Use this page to orient a first-time user before opening detailed analysis. Its cards and status panels summarize what is available in the selected store, and the model summary is limited to the records shown by its mode. Treat the Research view as a coverage and readiness summary; use Synthetic mode to practise navigation with visibly fictional examples.',
    'Interpret overview coverage': 'A count is meaningful only with its source, unit, date range, and data mode. The same technology count can refer to catalogue entries rather than technologies with valid observations. Read nearby warnings and source coverage before comparing cards. In the current Research store, empty model and prediction areas indicate missing prerequisites, not a zero-valued forecast.',
    'Technology Explorer overview': 'Explorer is the catalogue entry point. In Synthetic mode it provides fictional technology names and category filters; in Research mode it searches the Research catalogue and may expose source or coverage status. Use it to choose a record for inspection, not to infer that every listed technology has activity, adoption evidence, or a lifecycle label.',
    'Search for a technology': 'Start with a short distinctive name, then inspect the result rows before opening a profile. Search results can be filtered by the available category control. A matching catalogue entry means the technology can be selected; it does not guarantee that a dated indicator set or verified evidence exists. If a search is empty, try a shorter term and check the selected mode.',
    'Read Explorer results': 'Read each result as a catalogue record and check the visible category, identifiers, and available status fields together. The profile is the next step for examining a single technology. Do not treat a row in the catalogue as proof of community activity, company use, or a prediction; those claims require separate dated and validated evidence.',
    'Technology Profile overview': 'A profile brings one technology’s available information into one place. The displayed sections can include a community trend, seven feature values, a saved synthetic class, and saved probability scores. These sections have different meanings and provenance. Check their labels and the warning banner before explaining a value, especially when moving between the Research and Synthetic stores.',
    'Inspect feature values in a profile': 'The feature table pairs an indicator name with its value and unit. Use the methodology page to check how the demonstration value is calculated and what evidence it uses. A Research value may be absent because its required validated snapshot has not been created. Keep missing, unavailable, and measured zero distinct when describing the profile.',
    'Inspect saved class probabilities': 'The saved demo prediction is attached to generated indicator values and a generated lifecycle label. The probability table helps show how a classifier distributes scores across Growing, Stable, and Declining for that scenario. It is a teaching aid for reading the interface, not a live prediction about a technology and not evidence of calibrated probabilities.',
    'Global Rankings overview': 'Rankings sort the records available in the active mode using a chosen metric. Before reading the order, identify the metric, category, source scope, and period. Synthetic rankings are useful for learning how sorting and filtering work. Research rankings may be unavailable when the required observations are missing, and an empty result should remain an explicit limitation.',
    'Community Health in Synthetic mode': 'This page visualizes generated monthly question and answer activity for a selected fictional technology. Use its metrics and trend chart to practise reading the chosen time window and response pattern. The generated records are not scraped observations. Research mode has no valid monthly community rows because the source validation gate is blocked.',
    'Enterprise Adoption in Synthetic mode': 'The demo page groups fictional company and technology examples so the user can practise filtering by technology or organization. Its table and heatmap reflect generated scenarios, not a verified customer list or Kenyan market sample. Research mode currently lacks verified company–technology adoption observations, so do not carry the demo examples into claims about actual use.',
    'Developer Sentiment in Synthetic mode': 'The chart and table show generated monthly sentiment values for the selected fictional technology. Use the date and measure labels to describe what the display represents. The values are not survey responses. In Research mode, the stored survey summaries describe usage, interest, and admiration at a broader scope; they do not provide this monthly satisfaction series.',
    'Kenya Technology Landscape in Synthetic mode': 'This page is a geographic interface demonstration populated by fabricated Kenya-labelled records. Use the visible location and technology controls to see how the page responds, while keeping the synthetic warning in view. The Research database has no verified Kenya-specific technology observations, so the map cannot support claims about local adoption or developer activity.',
    'Model Laboratory overview': 'The laboratory lists saved results for the four generated demo classifiers and supports inspecting their saved evaluation. Its training action fits and saves all four models against synthetic records. The page does not train on PostgreSQL Research data. Use it to explain the workflow and the limitations of the demo evaluation, not to claim a completed empirical experiment.',
    'Retrain the synthetic model suite': 'Training updates the saved results for the Synthetic demonstration using generated examples. Confirm Synthetic mode and read the fictional-data warning before starting. Wait for the operation to finish, then review the results table. This action does not repair a source problem or create Research evidence.',
    'Select a saved model to inspect': 'Choose a model only after reviewing the run and metric table. The selector opens stored evaluation details; it does not retrain a selected algorithm. Compare class-level recall and support as well as aggregate accuracy. The demonstration models have weak Declining recall, so their best overall score should not be presented as reliable decline detection.',
    'Research Model Performance status': 'Research performance is displayed only when a valid registered model run exists. The current empty state is therefore an important result: dated indicator sets, labels, and a model run have not been saved in the Research database. Explain the missing prerequisites and show the source-quality page rather than substituting a synthetic score.',
    'Research Prediction Explorer status': 'Prediction Explorer withholds class counts until a validated dated indicator set and valid model run are available. This protects the user from interpreting an unsupported output as a stored prediction. The current Research store has neither prerequisite. Synthetic profile predictions are separate demo artifacts and must not be used to fill this empty state.',
    'SHAP global explanation': 'The global explanation summarizes feature contributions for the fitted synthetic Random Forest model. Read the horizontal bars as relative contributions within that model and dataset, not as causal effects or market importance. No Research model or Research explanation is available in PostgreSQL, so this visualization should only be demonstrated with the synthetic warning visible.',
    'SHAP individual explanation': 'The local view describes contributions for one selected generated scenario. Confirm the technology selector and synthetic provenance before explaining a bar. A positive or negative contribution describes how that feature shifted this model output for that input; it does not show what would happen if a real technology changed its behavior.',
    'Data Observatory in Synthetic mode': 'Use this page to review where the demonstration examples came from, how many records are available, and whether basic checks passed. These details help explain how the fictional examples were prepared. A successful integrity check confirms that the demonstration data can be read; it does not prove that the generated observations represent real people or organizations.',
    'Data Provenance and Quality in Research mode': 'Use this page to check the source and validation status before opening an analytical chart. The displayed publisher, coverage, dates, record counts, and quality notes help you judge what the application can support. A listed source is not automatically a valid dataset; read its coverage and quality status before using a result.',
    'Understand source validation': 'Before data can be used, TechPulse checks that the required fields are present and the values are plausible. The checked Stack Exchange input contains two cumulative records where unanswered questions exceed question volume, so the application blocks the source instead of hiding either record. Keep the original input unchanged. Use a corrected version only if an authoritative source confirms the correction, and record which file you used.',
    'Methodology and feature definitions': 'The methodology view is the place to distinguish implemented demo calculations from approved research measures. Compare each feature’s inputs, period, units, and missing-data rule with the written project requirements. The synthetic lifecycle thresholds do not match the project requirements rule, and the Company Diversity Score still needs an approved research definition.',
    'Export available results': 'Export only the rows currently shown after checking the active mode, filters, and visible row count. Research exports can be empty when the underlying evidence is absent; that is not a reason to export synthetic replacements. Preserve the downloaded file’s source and mode context when presenting or sharing it.',
    'Practical workflow: research readiness review': 'This workflow demonstrates the defensible Research path from database health to source coverage, validation, and empty analytical states. It helps an examiner distinguish an operational application from a completed experiment. The result should be a clear account of which prerequisites are present, which are blocked, and what evidence would be needed next.',
    'Practical workflow: synthetic application walkthrough': 'Use this route when the examiner needs to see populated charts and model controls. Start by displaying the synthetic warning, then move through Explorer, a profile, rankings, a source page, and the model lab. Narrate every populated value as generated data and switch back to Research mode before discussing the actual evidence boundary.',
}
PAGE_GUIDANCE.update({
    'Research question and intended users': 'As you review a result, ask whether the displayed evidence can answer the project question or only illustrate an interface. Look for dated community activity, documented company use, and a clearly defined sentiment measure. The current Research store does not supply enough verified records for the three-class experiment, so the application cannot answer the question yet.',
    'What the application can and cannot do': 'Use Research pages to inspect what is stored and where evidence is missing. Use Synthetic pages to see how searches, filters, rankings, charts, and model displays work when examples are available. A working control shows that the interface works; it does not prove that fictional values describe real technology use.',
    'Prepare the local project': 'Keep the project folder intact because the application relies on supporting data stored with it. Before your presentation, open the folder once and make sure you know its location. This prevents last-minute searching and lets you start the application from the correct place. Do not move or delete individual supporting files.',
    'Check Research database health': 'Use the status message in the sidebar as your first check. Then open Research Overview and Data Provenance and Quality to see whether sources are present and validated. If the sidebar reports a connection problem, stop interpreting Research charts and note the message; a populated Synthetic page cannot repair a Research connection.',
    'Understand the two operating modes': 'Select the mode deliberately before you open a page. The sidebar, warning, and page list change with your choice. For example, use Synthetic mode to practise opening a fictional technology profile, then return to Research mode to show the project’s actual evidence gaps. Say the mode name aloud when you switch.',
    'Read page banners and warnings': 'Pause at the top of each page before you read a metric. The banner tells you whether you are looking at stored Research evidence, a blocked source, or fictional Synthetic data. Keep the full banner visible in screenshots. If a warning appears, explain its scope before showing the chart or table below it.',
    'Indicator 1: Technology Health Score': 'On a Synthetic profile, find Technology Health Score in the feature table and read its unit with the value. The demonstration combines momentum, question quality, and inverse decay into a bounded score from 0 to 100. Use Methodology & About to see the formula. This score is not a verified assessment of a real technology’s health.',
    'Indicator 2: Growth Momentum Index': 'Find Growth Momentum Index on a Synthetic profile and check the percentage unit. The demo compares two adjacent three-month averages of question volume; it is not a forecast. Use the date range and source description to explain which periods are compared. Research mode does not currently have complete validated monthly inputs for this measure.',
    'Indicator 3: Question Quality Score': 'Read Question Quality Score as the share of generated questions that received an answer in the demonstration data. It does not rate technical quality, usefulness, or correctness. If you compare it with another indicator, keep the units and source separate. No validated Research value is currently available.',
    'Indicator 4: Company Diversity Score': 'The Synthetic Company Diversity Score counts distinct generated company sectors for the selected scenario. It does not measure the number of real adopters or the breadth of actual use. The Research definition still needs approval and verified company–technology evidence. Keep the demonstration label visible when you show this value.',
    'Indicator 5: Sentiment Delta': 'Read Sentiment Delta as the difference between the earliest and latest generated satisfaction points in a demo series. A positive change describes the synthetic example only; it is not a summary of real developer opinion. Research survey records report usage, interest, and admiration at a broader scope, not this monthly satisfaction measure.',
    'Indicator 6: Adoption Velocity': 'In Synthetic mode, Adoption Velocity counts generated new-company examples per quarter across a trailing four-quarter period. It is a demonstration calculation, not a measured rate of adoption. Research company profiles do not identify which technologies those organizations use, so the application cannot produce a verified adoption value.',
    'Indicator 7: Community Decay Rate': 'Read Community Decay Rate together with its percent unit and the two six-month windows. In the demo, a positive value means that the recent generated average is lower; a negative value can indicate growth. Research mode has no complete validated monthly series, and missing months are not treated as zero.',
    'Choose a ranking metric': 'Choose a measure that matches the question you want to explore, then read its definition before comparing rows. Activity is a record count; interest is a survey share; health and momentum use different inputs. These measures do not share one scale. In Research mode, an unavailable measure must stay unavailable rather than being filled with a demo value.',
    'Filter rankings by category': 'Use the category selector to narrow the displayed list, then check that your selected category appears on the page before you interpret the order. A filter changes which rows you see; it does not change the underlying observations. Clear the filter when you want to return to the full available list.',
    'Export and explain a ranking': 'Before you download a ranking, confirm the selected measure, category, data mode, and visible row count. Explain what the measure counts and which period it covers. A sorted table shows relative order within the available records; it is not a dedicated pairwise comparison and cannot rank records when supporting evidence is missing.',
    'Read the activity chart': 'Choose a fictional technology and read the chart’s date axis before describing a rise or fall. Check whether the page shows questions, answers, or another count. Compare adjacent periods only when the same source and time window are visible. A synthetic curve teaches the controls but says nothing about actual community activity.',
    'Research Community Health and blocked validation': 'In Research mode, open Community Health and read the validation notice above the chart area. The app reports the source problem and keeps invalid records out of the display. Use the page to explain why activity is unavailable; do not interpret an empty chart as zero questions or as evidence that a technology is declining.',
    'Handle missing community evidence': 'When community data are missing, read the message and open Data Provenance and Quality to identify the source and its status. Keep the failed input unchanged and record the issue. Do not replace missing months with zero or use the Synthetic chart as a substitute. Revisit the page only after a documented authoritative correction has passed validation.',
    'Filter company and sector examples': 'In the Synthetic Enterprise Adoption page, select a technology or organization and review the resulting rows and heatmap. The filter helps you practise the display; it does not verify that a named company uses the technology. Keep the Synthetic warning visible, and never quote generated examples as customer evidence.',
    'Research adoption evidence boundary': 'Use Research Overview and Data Provenance and Quality to distinguish a company profile from a verified technology-use record. A company can appear in the project without evidence that it uses a particular product. Do not infer adoption from a directory entry, job listing, public profile, or generated demo example.',
    'Research survey and skills signals': 'Select a survey year and geography, then read the measure name and source scope before you summarize the displayed share. Current Research summaries cover usage, interest, and admiration; they are not individual responses or a monthly satisfaction series. A global or unspecified geography must not be described as Kenya-specific evidence.',
    'Kenya evidence in Research mode': 'Open Kenya Technology Landscape in Research mode and read the message about verified observations. The current store has none, so a blank map or table is the honest result. Do not switch to Synthetic mode while describing local evidence; generated Kenya-labelled examples are fictional and cannot establish activity or adoption in Kenya.',
    'Understand chronological holdout': 'When you inspect a demo evaluation, note that the holdout is a later time period than the training data. This better resembles predicting forward than randomly mixing past and future records, but it does not make generated examples empirical. Check the dates and class counts before you explain any score.',
    'Understand accuracy, precision, and recall': 'Use the class rows to explain how a model behaves. Accuracy is the share of all test examples classified correctly. Precision asks how often predictions for a class are correct; recall asks how many actual examples of that class were found. For Declining, the demo models miss most examples, so overall accuracy is not enough.',
    'Understand weighted and macro F1': 'Read Weighted F1 and Macro F1 side by side. Weighted F1 gives more influence to classes with more test examples; Macro F1 gives each class equal influence. A gap between them can reveal uneven class performance. Neither measure guarantees that a model will work on real technologies or future data.',
    'Read the confusion matrix': 'Read each confusion-matrix row as the actual class and each column as the model’s predicted class. The diagonal shows correct classifications; other cells show which classes were confused. Use the class labels and support counts to describe the result. These demo counts come from generated records, not observed technology trajectories.',
    'Read time-series cross-validation': 'The time-series validation display compares model performance across several chronological splits. Look for variation between folds instead of reporting only the average. A large difference can mean that results depend on which time period was tested. These folds use generated demo data and do not establish future real-world performance.',
    'Synthetic saved predictions': 'Open a Synthetic Technology Profile and scroll to the saved inference section. Select the available demo model to inspect the saved class and score values. These results were generated for the demonstration store and are not live predictions. Do not quote them as Research outputs or as probabilities of real decline.',
    'Probability, score, and confidence': 'Read the exact label above each number. A model score can order classes without being a calibrated probability, and neither a score nor a probability guarantees a real outcome. Research mode currently has no stored predictions. Explain the warning before you show any Synthetic class score.',
    'Inspect research source details': 'Follow the source name, publisher, geography, date, and quality status shown in Data Provenance and Quality. This helps you explain where a Research summary came from and what it can represent. Some survey records lack enough detail to reconstruct the original collection process, so state that limitation when you use those summaries.',
    'Common errors: database and launch': 'If you cannot open the page, check the browser address and whether the application is still running. If Research mode reports a connection problem, read the sidebar message and ask the person who set up TechPulse for help. Do not change database settings or switch to Synthetic unless you intend to show fictional data.',
    'Common errors: search and empty pages': 'If a search has no results, remove extra words, check spelling, and clear any category filter. If a Research chart remains empty, check the mode banner and source status before trying another technology. Do not assume the missing value is zero; a source may be blocked or no validated record may exist.',
    'Common warnings: source validation and missing inputs': 'Read a warning before continuing to the chart. It identifies a limit on the evidence, such as invalid community counts or a missing observation period. Preserve the warning when you present a screenshot. A warning can be the correct research result and does not necessarily mean the application has failed.',
    'Training action fails': 'The training button is available only in Synthetic mode and runs the complete demo model set. If an error appears, keep the message and stop clicking until you have checked the existing saved results. You cannot use this button to train a Research model. Do not reset the demo store to hide an error.',
    'Export and display troubleshooting': 'If a chart is slow, wait for the page to finish updating before you click again. If no download button appears, that page may not offer an export or the current result may be empty. Check the mode, filters, and visible rows. Save exported Synthetic files with a name that keeps their fictional status clear.',
    'Frequently asked questions': 'Use these answers to explain what you can demonstrate today. You can browse the Synthetic interface and show the current Research evidence boundary. You cannot generate a valid Research prediction from the records presently stored. If an examiner asks about an empty page, show the validation or coverage message that explains it.',
    'FAQ: model and ranking questions': 'If you are asked which model is best, compare class-level recall and support as well as overall scores. If you are asked for a pairwise technology comparison, explain that the available view is a sorted ranking table. If you are asked for a prediction, state whether you are viewing Synthetic or Research mode first.',
    'Messages and meanings quick reference': 'Match the message on screen to the explanation in this section, then check the current mode and page. For example, “No valid persisted predictions exist” means the Research prerequisites are absent; it is not a prediction of zero decline. Capture the entire warning if you need to report the screen.',
    'Reference: seven indicator definitions': 'Use these definitions when you need to explain the numbers displayed on a Synthetic Technology Profile. Check the matching row in Methodology & About for its period and units. These definitions describe the current interface demonstration; they do not replace an approved research measure or provide a Research score.',
    'Reference: enterprise and sentiment indicators': 'Before you interpret these values, identify whether they come from generated company examples or from stored survey summaries. Synthetic diversity and satisfaction values are different from verified adoption and survey interest. Research values remain unavailable until appropriate evidence and approved definitions exist.',
    'Reference: community decay indicator': 'Use the two time windows to explain the direction of this percentage. A negative number is not automatically an error, and a positive number is not proof of a long-term decline. Check that all required months are present and keep the Synthetic label visible when you demonstrate the calculation.',
    'Reference: current evidence boundary': 'Use this section when you need a concise and accurate summary of the project’s current data. Read the observation date, distinguish catalogue entries from observations, and label survey summaries by their global or unspecified scope. Report blocked sources and missing model outputs alongside the counts.',
    'Research Technology Explorer status': 'In Research mode, search for a catalogue entry and read its status panel. The entry confirms that the name is listed; it does not mean a complete indicator set, lifecycle label, or prediction exists. Use the source details to explain which records are present and which are missing.',
    'Research Technology Rankings status': 'Choose a measure that has a definition and supporting records, then read its period and source coverage before comparing rows. Research Activity counts source records rather than unique technologies in use. When Momentum is unavailable, explain that no time-based series is available instead of placing the technology at the bottom.',
    'Live Technology Intelligence status': 'Open this page in Research mode to check whether time-stamped live observations have been recorded. The current page reports that none are available. If you see an empty state, explain the missing source rather than substituting company-directory profiles or Synthetic examples.',
    'About and responsible use': 'Read the interpretation and responsible-use sections before you present a model output. Separate an observed source record from a calculated feature and from a model prediction. Keep the mode warning visible, describe the evidence limits, and avoid claims about guaranteed adoption, employment, or success.',
})
for item in PAGES:
    item['guidance'] = PAGE_GUIDANCE.get(item['title'], '')

def set_font(style, name="Times New Roman", size=12, bold=None, color=None):
    style.font.name = name
    style.font.size = Pt(size)
    if bold is not None: style.font.bold = bold
    style.font.color.rgb = RGBColor(0,0,0)
    rpr = style.element.get_or_add_rPr()
    rfonts = rpr.rFonts
    if rfonts is None:
        rfonts = OxmlElement('w:rFonts'); rpr.append(rfonts)
    for attr in ('asciiTheme','hAnsiTheme','eastAsiaTheme','cstheme'):
        rfonts.attrib.pop(qn('w:'+attr),None)
    for key in ('ascii','hAnsi','cs','eastAsia'):
        rfonts.set(qn('w:'+key), name)

def field(paragraph, instruction, result=""):
    r=OxmlElement('w:r'); b=OxmlElement('w:fldChar'); b.set(qn('w:fldCharType'),'begin'); r.append(b); paragraph._p.append(r)
    r=OxmlElement('w:r'); i=OxmlElement('w:instrText'); i.set(qn('xml:space'),'preserve'); i.text=instruction; r.append(i); paragraph._p.append(r)
    r=OxmlElement('w:r'); s=OxmlElement('w:fldChar'); s.set(qn('w:fldCharType'),'separate'); r.append(s); paragraph._p.append(r)
    if result:
        r=OxmlElement('w:r'); t=OxmlElement('w:t'); t.text=result; r.append(t); paragraph._p.append(r)
    r=OxmlElement('w:r'); e=OxmlElement('w:fldChar'); e.set(qn('w:fldCharType'),'end'); r.append(e); paragraph._p.append(r)

def index_entry(paragraph, term):
    # XE fields are hidden by Word and produce real page references in the generated index.
    safe=term.replace('"','“')
    field(paragraph, f' XE "{safe}" ')

def set_cell_shading(cell, fill):
    tcpr=cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),fill); tcpr.append(shd)

def set_cell_borders(cell):
    tcpr=cell._tc.get_or_add_tcPr()
    borders=tcpr.find(qn('w:tcBorders'))
    if borders is None:
        borders=OxmlElement('w:tcBorders'); tcpr.append(borders)
    for edge in ('top','left','bottom','right','insideH','insideV'):
        tag=qn('w:'+edge); element=borders.find(tag)
        if element is None: element=OxmlElement('w:'+edge); borders.append(element)
        element.set(qn('w:val'),'single'); element.set(qn('w:sz'),'6'); element.set(qn('w:space'),'0'); element.set(qn('w:color'),'000000')
    margins=tcpr.find(qn('w:tcMar'))
    if margins is None: margins=OxmlElement('w:tcMar'); tcpr.append(margins)
    for edge,value in (('top','80'),('bottom','80'),('start','100'),('end','100')):
        tag=qn('w:'+edge); el=margins.find(tag)
        if el is None: el=OxmlElement('w:'+edge); margins.append(el)
        el.set(qn('w:w'),value); el.set(qn('w:type'),'dxa')

def add_table(doc, rows, widths=None, caption=None):
    t=doc.add_table(rows=0,cols=len(rows[0])); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'
    for ri,row in enumerate(rows):
        cells=t.add_row().cells
        for ci,val in enumerate(row):
            cells[ci].text=str(val); cells[ci].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            set_cell_shading(cells[ci],'FFFFFF'); set_cell_borders(cells[ci])
            for p in cells[ci].paragraphs:
                p.paragraph_format.space_after=Pt(2); p.paragraph_format.keep_together=True
                for run in p.runs: run.font.name='Times New Roman'; run.font.size=Pt(10); run.font.color.rgb=RGBColor(0,0,0); run.bold=(ri==0)
    if widths:
        for row in t.rows:
            for c,w in zip(row.cells,widths): c.width=Inches(w)
    if caption:
        cap=doc.add_paragraph(style='Caption'); cap.alignment=WD_ALIGN_PARAGRAPH.CENTER
        cap.add_run('Table '); field(cap,' SEQ Table \\* ARABIC ', '1'); cap.add_run('. '+caption)
    return t

