def centered(text,size,bold=False,color=(0,0,0),space=10):
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(space)
    r=p.add_run(text); r.font.name='Times New Roman'; r.font.size=Pt(size); r.bold=bold; r.font.color.rgb=RGBColor(0,0,0)
    return p
