current_chapter=None; fig_count=0; table_count=0; page_index=[]; seen_figures=set(); missing_figures=set()
reference_started=False
for item in PAGES:
    ch=item['chapter']
    title=item['title']
    if ch == 0 and not reference_started:
        h=doc.add_heading('Reference Materials',level=1)
        h.paragraph_format.page_break_before=True
        reference_started=True
    if ch:
        if ch!=current_chapter:
            current_chapter=ch
            h=doc.add_heading(f'Chapter {ch}. {title if title not in [x["title"] for x in PAGES if x["chapter"]==ch][1:] else title}',level=1)
            h.paragraph_format.page_break_before=True
        else:
            doc.add_heading(title,level=2)
    else:
        doc.add_heading(title,level=2)
    page_index.append({'chapter':ch,'title':title})
    index_entry(doc.paragraphs[-1],title)
    p=doc.add_paragraph(clean_figure_refs(item['overview'])); p.paragraph_format.keep_together=True
    if item.get('guidance'):
        p=doc.add_paragraph(item['guidance']); p.paragraph_format.keep_together=True
    if item['steps']:
        label=doc.add_paragraph(); label.paragraph_format.keep_with_next=True
        rr=label.add_run('Do this'); rr.bold=True; rr.font.color.rgb=RGBColor(0,0,0)
        for step_no,step in enumerate(item['steps'],1):
            p=doc.add_paragraph(); p.paragraph_format.left_indent=Inches(.28); p.paragraph_format.first_line_indent=Inches(-.25); p.paragraph_format.space_after=Pt(2); p.paragraph_format.keep_together=True; p.add_run(f'{step_no}. {clean_figure_refs(step)}')
    if item['figure']:
        path=SCREEN/(item['figure']+'_annotated.png')
        if not path.exists():
            missing_figures.add(item['figure'])
        elif item['figure'] not in seen_figures:
            p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_before=Pt(2); p.paragraph_format.space_after=Pt(2); p.paragraph_format.keep_with_next=True
            p.add_run().add_picture(str(path),width=Inches(6.15))
            fig_count+=1
            seen_figures.add(item['figure'])
            key=doc.add_paragraph(); key.alignment=WD_ALIGN_PARAGRAPH.CENTER; key.paragraph_format.space_after=Pt(1); key.paragraph_format.keep_with_next=True
            rr=key.add_run('A — Page navigation    B — Data mode    C — Main page content'); rr.font.name='Times New Roman'; rr.font.size=Pt(8.5)
            cap=doc.add_paragraph(style='Caption'); cap.alignment=WD_ALIGN_PARAGRAPH.CENTER
            cap.paragraph_format.keep_together=True
            cap.add_run('Figure '); field(cap,' SEQ Figure \\* ARABIC ',str(fig_count))
            caption_note=(item["figure_note"] or item["title"]).rstrip().rstrip('.')
            cap.add_run(f'. {caption_note}. ')
            cap.add_run('Captured from the running TechPulse application. Synthetic values are fictional; see the mode banner.').italic=True
    result_blocks=[(label,key) for label,key in [('Expected result','result'),('Understanding the result','interpret'),('Common issue','issue'),('Related task','related')] if item[key]]
    for block_no,(label,key) in enumerate(result_blocks):
        text=item[key]
        p=doc.add_paragraph(); p.paragraph_format.keep_together=True; p.paragraph_format.space_after=Pt(4)
        p.paragraph_format.keep_with_next=block_no < len(result_blocks)-1
        r=p.add_run(label+': '); r.bold=True; r.font.color.rgb=RGBColor(0,0,0)
        p.add_run(clean_figure_refs(text))

# Back matter glossary (alphabetical, one concise page-group per letter range)
glossary = [
('Accuracy','The share of test records whose predicted class matches the reference label.'),('Adoption velocity','A rate of dated technology-use evidence over a stated period; the current Research value is unavailable.'),('Answer rate','The share of observed questions that have at least one answer, subject to the source definition.'),('As-of date','The latest date up to which an input is allowed to contribute to a dated indicator set.'),('Baseline','A simple reference method used to judge whether a more complex model adds value.'),('Research database','The structured PostgreSQL store used by Research mode.'),('Classification','Assigning an input to one of a set of named classes.'),('Community activity','A measured time series of developer questions and answers from a named source.'),('Confusion matrix','A table of actual class counts against predicted class counts.'),('Cross-validation','Repeated training and validation on different time-ordered slices to examine variation.'),('CSV','Comma-separated values; a text file format used by supported table exports.'),('Data provenance','Information about where a record came from and how it was collected or transformed.'),('Data validation','Checks that an input has expected fields and plausible values before use.'),('Dataset','A structured collection of related records.'),('Feature','An input measurement supplied to a machine-learning model.'),('Feature engineering','Preparing model inputs from recorded evidence using documented rules.'),('Feature snapshot','A set of feature values tied to a technology and an as-of date.'),('F1-score','A combined measure of precision and recall.'),('Holdout','A later set of observations reserved for evaluation after training.'),('Index','An alphabetical list at the end of this manual that helps you find a topic and its page number.'),('JSON','JavaScript Object Notation; a structured text format for data exchange.'),('Lifecycle classification','A label such as Growing, Stable, or Declining assigned under a stated rule.'),('Machine learning','Methods that fit patterns from data to classify or estimate outcomes.'),('Macro F1','The arithmetic mean of class F1 scores, giving each class equal weight.'),('Metric','A defined numeric measure used to describe a record, model, or evaluation.'),('Model','A fitted method that maps input features to an output.'),('PostgreSQL','The relational database used by Research mode.'),('Precision','Among predictions assigned to a class, the share matching that class in the evaluation labels.'),('Prediction','A model output for an input; it is not automatically a fact or a calibrated probability.'),('Probability score','A model-produced class score; it is a calibrated probability only if calibration is documented.'),('Recall','Among records belonging to a class, the share the model correctly identifies.'),('Research mode','The application mode that reads official PostgreSQL research records.'),('Sentiment analysis','A method for summarizing expressed positive, neutral, or negative tone; generated values in the demo are not real responses.'),('SHAP','Shapley Additive Explanations; a method that attributes parts of a model output to input features.'),('Synthetic data','Generated records made for demonstration or testing; not observed empirical facts.'),('Technology adoption','Evidence that an organization uses a technology, requiring a documented source and relationship.'),('Training data','Records used to fit model parameters.'),('Validation data','Records used during model selection or tuning, kept separate from final testing.'),('Weighted F1','A class F1 average weighted by the number of reference examples in each class.'),('XGBoost','An implementation of gradient-boosted decision trees; one of the four synthetic demo classifiers.'),
]
for group,terms in [('A-H',[x for x in glossary if x[0][0].upper() in 'ABCDEFGH']),('I-P',[x for x in glossary if x[0][0].upper() in 'IJKLMNOP']),('Q-Z',[x for x in glossary if x[0][0].upper() in 'QRSTUVWXYZ'])]:
    doc.add_heading('Glossary '+group,level=1)
    for term,definition in terms:
        p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(2); p.paragraph_format.keep_together=True; r=p.add_run(term+'. '); r.bold=True; p.add_run(definition); index_entry(p,term)

